<?php
namespace App\services;
use App\config\Database;
use RuntimeException;
use ZipArchive;
final class FileService {
    private array $allowed=['pdf'=>['application/pdf'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/zip'],'txt'=>['text/plain'],'csv'=>['text/csv','text/plain','application/csv','application/vnd.ms-excel']];
    public function upload(array $user,array $file):array{$err=$file['error']??UPLOAD_ERR_NO_FILE;if($err!==UPLOAD_ERR_OK)throw new RuntimeException('Falha no upload do arquivo.');$max=max(1,(int)env('MAX_UPLOAD_MB','10'))*1024*1024;$size=(int)($file['size']??0);if($size<=0||$size>$max)throw new RuntimeException('Arquivo vazio ou acima do limite de '.env('MAX_UPLOAD_MB','10').' MB.');$original=mb_substr(basename((string)($file['name']??'arquivo')),0,255);$ext=strtolower(pathinfo($original,PATHINFO_EXTENSION));if(!isset($this->allowed[$ext]))throw new RuntimeException('Formato não permitido. Use PDF, DOCX, TXT ou CSV.');$finfo=new \finfo(FILEINFO_MIME_TYPE);$mime=(string)($finfo->file($file['tmp_name'])?:'');if(!in_array($mime,$this->allowed[$ext],true))throw new RuntimeException('O conteúdo do arquivo não corresponde à extensão informada.');
        $dir=dirname(__DIR__).'/storage/uploads/'.(int)$user['company_id'];if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Não foi possível preparar o armazenamento.');$stored=bin2hex(random_bytes(24)).'.'.$ext;$path=$dir.'/'.$stored;if(!move_uploaded_file($file['tmp_name'],$path))throw new RuntimeException('Não foi possível salvar o arquivo.');@chmod($path,0640);$sha=hash_file('sha256',$path);$text=$this->extract($path,$ext);$text=mb_substr($this->normalizeText($text),0,300000);
        $pdo=Database::get();$pdo->prepare('INSERT INTO uploaded_files(user_id,company_id,original_name,stored_name,extension,mime_type,size_bytes,sha256,extracted_text,created_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())')->execute([$user['id'],$user['company_id'],$original,$stored,$ext,$mime,$size,$sha,$text]);return ['id'=>(int)$pdo->lastInsertId(),'name'=>$original,'extension'=>$ext,'mime_type'=>$mime,'size'=>$size,'extracted'=>trim($text)!=='','extraction_note'=>$ext==='pdf'&&trim($text)===''?'PDF armazenado com segurança. Como não houve extração local, o Agente de Documentos pode enviar o PDF diretamente ao Gemini quando esse provider estiver configurado.':null];}
    public function forUser(int $fileId,array $user):array{$s=Database::get()->prepare('SELECT id,original_name,stored_name,extension,mime_type,size_bytes,extracted_text,company_id FROM uploaded_files WHERE id=? AND user_id=? AND company_id=?');$s->execute([$fileId,$user['id'],$user['company_id']]);$f=$s->fetch();if(!$f)throw new RuntimeException('Arquivo não encontrado.');$f['storage_path']=dirname(__DIR__).'/storage/uploads/'.$f['company_id'].'/'.$f['stored_name'];return $f;}
    public function textForUser(int $fileId,array $user):array{$f=$this->forUser($fileId,$user);if(trim((string)$f['extracted_text'])==='')throw new RuntimeException('Não foi possível extrair texto deste arquivo localmente. Para PDFs, configure o agente com Gemini para análise nativa do arquivo ou habilite pdftotext/Poppler.');return $f;}
    public function delete(int $fileId,array $user):void{$pdo=Database::get();$s=$pdo->prepare('SELECT stored_name,company_id FROM uploaded_files WHERE id=? AND user_id=? AND company_id=?');$s->execute([$fileId,$user['id'],$user['company_id']]);$f=$s->fetch();if(!$f)return;$path=dirname(__DIR__).'/storage/uploads/'.$f['company_id'].'/'.$f['stored_name'];if(is_file($path))@unlink($path);$pdo->prepare('DELETE FROM uploaded_files WHERE id=? AND user_id=?')->execute([$fileId,$user['id']]);}
    private function extract(string $path,string $ext):string{if(in_array($ext,['txt','csv'],true))return (string)file_get_contents($path);if($ext==='docx'&&class_exists(ZipArchive::class)){$z=new ZipArchive();if($z->open($path)===true){$xml=$z->getFromName('word/document.xml')?:'';$z->close();$xml=str_replace(['</w:p>','</w:tr>','<w:tab/>'],["\n","\n","\t"],$xml);return html_entity_decode(strip_tags($xml),ENT_QUOTES|ENT_XML1,'UTF-8');}}if($ext==='pdf'&&function_exists('shell_exec')&&!str_contains((string)ini_get('disable_functions'),'shell_exec')){$bin=trim((string)@shell_exec('command -v pdftotext 2>/dev/null'));if($bin!==''){$tmp=tempnam(sys_get_temp_dir(),'equipeai_pdf_');@shell_exec(escapeshellcmd($bin).' -layout '.escapeshellarg($path).' '.escapeshellarg($tmp).' 2>/dev/null');$text=is_file($tmp)?(string)file_get_contents($tmp):'';@unlink($tmp);return $text;}}return '';}
    private function normalizeText(string $text):string{$text=str_replace("\0",'',$text);$text=preg_replace('/[ \t]+/u',' ',$text)??$text;$text=preg_replace('/\n{4,}/u',"\n\n\n",$text)??$text;return trim($text);}
}
